/* UI helpers for Testing (user-level page actions only). Load: eval((await (await fetch('/devlog/ui')).json()).src)  (after th) */
(() => {
const W = window, slp = ms => new Promise(r => setTimeout(r, ms)); W.slp = slp;
W.arm = k => { const b = [...document.querySelectorAll('button')].filter(b => b.offsetParent && b.textContent.trim().startsWith(k + ' ') && b.getBoundingClientRect().y < 100)[0]; b.click(); return b.textContent };
W.cb = () => [...document.querySelectorAll('button')].filter(b => /^[1-9]\s*[＋✓+]/.test(b.textContent.trim()) && b.offsetParent).map(b => b.textContent.trim());
W.sev = (type, x, y, b) => { const el = document.elementFromPoint(x, y); const o = { clientX: x, clientY: y, bubbles: true, cancelable: true, pointerId: 1, button: 0, buttons: b, isPrimary: true, pointerType: 'mouse' }; el.dispatchEvent(new PointerEvent(type.replace('mouse', 'pointer'), o)); el.dispatchEvent(new MouseEvent(type, o)); return el.tagName };
/* needs a tall viewport (resize 1024x1800) so the map svg is on screen. click the LARGEST visible video canvas of size WdxH at video pixel (px,py) */
W.sclick = (px, py, Wd, H) => { const cv = [...document.querySelectorAll('canvas')].filter(e => e.offsetParent && e.width == Wd && e.height == H).sort((a, b) => b.getBoundingClientRect().width - a.getBoundingClientRect().width)[0]; const r = cv.getBoundingClientRect(); const x = r.x + px * r.width / Wd, y = r.y + py * r.height / H; for (const [t, b] of [['pointerdown', 1], ['mousedown', 1], ['pointerup', 0], ['mouseup', 0], ['click', 0]]) { const o = { clientX: x, clientY: y, bubbles: true, cancelable: true, pointerId: 1, button: 0, buttons: b, isPrimary: true, pointerType: 'mouse' }; cv.dispatchEvent(t.startsWith('pointer') ? new PointerEvent(t, o) : new MouseEvent(t, o)); } return [Math.round(r.width), Math.round(r.height)] };
/* drag on the video canvas from video px a to b */
W.vdrag = async (ax, ay, bx, by, Wd, H) => { const cv = [...document.querySelectorAll('canvas')].filter(e => e.offsetParent && e.width == Wd && e.height == H).sort((a, b) => b.getBoundingClientRect().width - a.getBoundingClientRect().width)[0]; const r = cv.getBoundingClientRect(); const X = p => r.x + p * r.width / Wd, Y = p => r.y + p * r.height / H; const ev = (t, x, y, b) => { const o = { clientX: x, clientY: y, bubbles: true, cancelable: true, pointerId: 1, button: 0, buttons: b, isPrimary: true, pointerType: 'mouse' }; cv.dispatchEvent(t.startsWith('pointer') ? new PointerEvent(t, o) : new MouseEvent(t, o)); }; ev('pointerdown', X(ax), Y(ay), 1); ev('mousedown', X(ax), Y(ay), 1); for (let k = 1; k <= 5; k++) { await slp(30); const x = X(ax + (bx - ax) * k / 5), y = Y(ay + (by - ay) * k / 5); ev('pointermove', x, y, 1); ev('mousemove', x, y, 1); } ev('pointerup', X(bx), Y(by), 0); ev('mouseup', X(bx), Y(by), 0); return 'ok' };
W.sdrag = async (x1, y1, x2, y2) => { sev('mousedown', x1, y1, 1); for (let k = 1; k <= 5; k++) { await slp(30); sev('mousemove', x1 + (x2 - x1) * k / 5, y1 + (y2 - y1) * k / 5, 1); } const t = sev('mouseup', x2, y2, 0); document.elementFromPoint(x2, y2).dispatchEvent(new MouseEvent('click', { clientX: x2, clientY: y2, bubbles: true })); return t };
W.sclk = (x, y) => { sev('mousedown', x, y, 1); sev('mouseup', x, y, 0); document.elementFromPoint(x, y).dispatchEvent(new MouseEvent('click', { clientX: x, clientY: y, bubbles: true })) };
W.newRef = async n => { W.scrollTo(0, 0); [...document.querySelectorAll('button')].find(x => x.textContent.includes('วาด Reference')).click(); await slp(300); const e = document.querySelector('#askN'); e.value = String(n); e.dispatchEvent(new Event('input')); document.querySelector('#askOk').click(); await slp(300); return JSON.parse(th.state()).status };
W.typePts = async s => { const i = document.querySelector('#sPts'); i.focus(); i.value = s; i.dispatchEvent(new Event('input', { bubbles: true })); i.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, bubbles: true })); i.dispatchEvent(new Event('change', { bubbles: true })); await slp(300); return JSON.parse(th.state()).status };
W.refSels = () => [...document.querySelectorAll('select')].filter(s => [...s.options].some(o => /^r\d+/.test(o.value)));
W.refIds = () => [...refSels()[0].options].map(o => o.value).filter(Boolean);
W.setRef = (ci, v) => { const s = refSels()[ci]; s.value = v; s.dispatchEvent(new Event('change')) };
W.full = async i => { document.querySelectorAll('button[title^="กล้องนี้เต็มจอ"]')[i].click(); await slp(500); };
W.exitFull = async () => { const b = [...document.querySelectorAll('.card.full button')].find(b => b.offsetParent && (b.title || '').startsWith('กล้องนี้เต็มจอ')); if (b) { b.click(); await slp(400); } return !!b };
/* map ref with typed coords: n points 'x,y; ...' (exit full view first) */
W.mapRef = async (pts) => { await W.exitFull(); const n = pts.split(';').length; await newRef(n); const sv = [...document.querySelectorAll('svg')].map(e => e.getBoundingClientRect()).filter(r => r.width > 200)[0]; if (n == 4) { await sdrag(sv.x + 0.25 * sv.width, sv.y + 0.25 * sv.height, sv.x + 0.55 * sv.width, sv.y + 0.6 * sv.height); } else for (let k = 0; k < n; k++) { const a = 2 * Math.PI * k / n; sclk(sv.x + (0.45 + 0.2 * Math.cos(a)) * sv.width, sv.y + (0.45 + 0.2 * Math.sin(a)) * sv.height); await slp(200); } await slp(300); await typePts(pts); return refIds().slice(-1)[0] };
/* tie camera ci (canvas WdxH) with points P=[[x,y],..] to ref id */
W.tie = async (ci, id, P, Wd, H) => { setRef(ci, id); await slp(300); scrollTo(0, 0); await full(ci); await slp(300); for (let k = 1; k <= P.length; k++) { arm(k); await slp(200); sclick(P[k - 1][0], P[k - 1][1], Wd, H); await slp(250); } await slp(500); await W.exitFull(); return JSON.parse(th.state()).cams[ci] };
W.offr = () => [...document.querySelectorAll('button')].filter(b => b.offsetParent && b.textContent.includes('ใช้ค่านี้') && /คนตรงกับกล้องอื่น/.test(b.parentElement.textContent)); /* people-tie offers only: a click-tied camera also gets a 'จัดให้ตรงกับกล้องอื่น' offer that moves it toward people-tied cameras; do not auto-accept that one */
W.loadScen = async id => { const s = document.querySelector('#vset'); s.value = id; s.dispatchEvent(new Event('change')); await slp(3000); W.confirm = () => true; const b = document.querySelector('button[title^="ลบแผนที่"]'); b && b.click(); await slp(2000); return JSON.parse(th.state()).status };
/* grab frames: cams = list of cam idx, ts = times; POSTs to /devlog/<name> */
W.grab = async (name, cams, ts) => { const out = {}; const vs = [...document.querySelectorAll('video')]; for (const i of cams) for (const t of ts) { const v = vs[i]; v.currentTime = t; await new Promise(r => v.addEventListener('seeked', r, { once: true })); const c = document.createElement('canvas'); c.width = v.videoWidth; c.height = v.videoHeight; const g = c.getContext('2d'); g.drawImage(v, 0, 0); if (W.GRID) { g.font = '9px sans-serif'; for (let x = 0; x < c.width; x += W.GRID) { g.strokeStyle = x % (W.GRID * 5) ? 'rgba(0,200,200,.6)' : 'rgba(255,255,0,.9)'; g.beginPath(); g.moveTo(x + .5, 0); g.lineTo(x + .5, c.height); g.stroke(); if (x % (W.GRID * 2) == 0) { g.fillStyle = 'red'; g.fillText(x, x + 1, 9); } } for (let y = 0; y < c.height; y += W.GRID) { g.strokeStyle = y % (W.GRID * 5) ? 'rgba(0,200,200,.6)' : 'rgba(255,255,0,.9)'; g.beginPath(); g.moveTo(0, y + .5); g.lineTo(c.width, y + .5); g.stroke(); if (y % (W.GRID * 2) == 0) { g.fillStyle = 'red'; g.fillText(y, 1, y - 1); } } } out['c' + i + '_' + t] = c.toDataURL('image/png'); } const r = await fetch('/devlog/' + name, { method: 'POST', body: JSON.stringify(out) }); return [r.status, vs.map(v => v.videoWidth + 'x' + v.videoHeight)] };
/* wait up to sec, accept people offers; the offer text has no height, so the height is checked after accepting and the tie is undone when outside [hmin,hmax] (set W.HMAX per scenario) */
W.__log = [];
/* hidden pane throttles timers: start autoAcc(300) without await, then poll __log / th.state() */
W.autoAcc = async (sec, hmin = 1.2, hmax = W.HMAX || 8) => { for (let k = 0; k < sec / 2 && !W.__rdone; k++) { await slp(2000); for (const b of offr()) { const t = b.parentElement.textContent; const hm = t.match(/สูง\s*([\d.]+)/); const h = hm ? +hm[1] : null; const ok = h === null || (h >= hmin && h <= hmax); W.__log.push(JSON.parse(th.state()).vt[0] + (ok ? ' ACC | ' : ' SKIP | ') + 'cam' + [...document.querySelectorAll('.card')].indexOf(b.closest('.card')) + ' ' + ((t.match(/คนตรงกับกล้องอื่น.*?จุด[^ใ]*/) || [t.slice(-120)])[0])); if (ok) { const card = b.closest('.card'), ci = [...document.querySelectorAll('.card')].indexOf(card); b.click(); await slp(600); const h2 = JSON.parse(th.state()).cams[ci]?.[3]?.h; if (h2 != null && (h2 < hmin || h2 > hmax)) { const u = [...document.querySelectorAll('.card')[ci].querySelectorAll('button')].find(x => x.textContent.includes('ยกเลิกการปรับ')); if (u) { u.click(); await slp(400); } W.__log.push('   UNDONE cam' + ci + ' implausible height ' + h2 + (u ? '' : ' (no undo button found)')); } else W.__log.push('   -> cam' + ci + ' h ' + h2); } } } return [W.__rdone ? 'fin' : 'run', JSON.parse(th.state()).cams.map(c => c[3] && c[3].h), JSON.parse(th.state()).vt[0]] };
W.play = name => { document.querySelector('#rewind').click(); W.__rdone = null; th.run(name).then(r => W.__rdone = r || 'done').catch(e => W.__rdone = 'err ' + e); return 'started' };
/* --- added by T7 --- */
/* per-point residuals of camera ci (clicks each '<k> ✓' button and reads the point bar) */
W.ptRes = async ci => { const o = []; for (let k = 1; k <= 12; k++) { const b = [...document.querySelectorAll('.card')[ci].querySelectorAll('button')].find(b => b.offsetParent && new RegExp('^' + k + '\s*✓').test(b.textContent.trim())); if (!b) continue; b.click(); await slp(200); const pb = document.querySelectorAll('.card')[ci].querySelector('.ptbar'); o.push(k + ':' + (pb ? pb.querySelector('span')?.textContent : '?')); } document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true })); return o };
/* remove clicked point k of camera ci (select it, then the bin button in the point bar) */
W.dropPt = async (ci, k) => { const b = [...document.querySelectorAll('.card')[ci].querySelectorAll('button')].find(b => b.offsetParent && new RegExp('^' + k + '\s*✓').test(b.textContent.trim())); b.click(); await slp(250); const pb = document.querySelectorAll('.card')[ci].querySelector('.ptbar'); [...pb.querySelectorAll('button')].find(x => x.textContent.includes('🗑')).click(); await slp(400); return JSON.parse(th.state()).cams[ci] };
/* zoomed crop with a labelled grid (video px): src = video or canvas; returns a PNG dataURL to POST to /devlog/<name> */
W.cropGrid = (src, x0, y0, w, h, s, step) => { const c = document.createElement('canvas'); c.width = w * s; c.height = h * s; const g = c.getContext('2d'); g.drawImage(src, x0, y0, w, h, 0, 0, w * s, h * s); g.font = '10px sans-serif'; for (let x = 0; x <= w; x += step) { g.strokeStyle = x % (step * 5) ? 'rgba(0,200,200,.4)' : 'rgba(255,255,0,.9)'; g.beginPath(); g.moveTo(x * s + .5, 0); g.lineTo(x * s + .5, h * s); g.stroke(); if (x % (step * 5) == 0) { g.fillStyle = 'red'; g.fillText(x0 + x, x * s + 1, 10); } } for (let y = 0; y <= h; y += step) { g.strokeStyle = y % (step * 5) ? 'rgba(0,200,200,.4)' : 'rgba(255,255,0,.9)'; g.beginPath(); g.moveTo(0, y * s + .5); g.lineTo(w * s, y * s + .5); g.stroke(); if (y % (step * 5) == 0) { g.fillStyle = 'red'; g.fillText(y0 + y, 1, y * s - 1); } } return c.toDataURL('image/png') };
/* people-free background of camera ci: per pixel, the frame at brightness quantile q (0.9 works on bright floors) over n frames; returns a canvas for cropGrid */
W.bgPct = async (ci, n, q) => { const v = [...document.querySelectorAll('video')][ci]; const Wd = v.videoWidth, H = v.videoHeight; const c = document.createElement('canvas'); c.width = Wd; c.height = H; const g = c.getContext('2d'); const fr = []; const D = v.duration; for (let k = 0; k < n; k++) { v.currentTime = (k + 0.5) * D / n; await new Promise(r => v.addEventListener('seeked', r, { once: true })); g.drawImage(v, 0, 0); fr.push(g.getImageData(0, 0, Wd, H).data); } const o = g.getImageData(0, 0, Wd, H); const lum = new Float32Array(n), idx = [...Array(n).keys()]; for (let p = 0; p < o.data.length; p += 4) { for (let k = 0; k < n; k++) lum[k] = fr[k][p] + fr[k][p + 1] + fr[k][p + 2]; idx.sort((a, b) => lum[a] - lum[b]); const k = idx[Math.floor(q * (n - 1))]; o.data[p] = fr[k][p]; o.data[p + 1] = fr[k][p + 1]; o.data[p + 2] = fr[k][p + 2]; o.data[p + 3] = 255; } g.putImageData(o, 0, 0); return c };
/* play the clip N times in a row (dumps <name>-p1..pN), accepting offers; poll __pl / __fin / __log. Wait with tool-side waits (computer wait 10 s in a browser_batch): page timers are throttled while the pane is hidden */
W.playN = (name, N) => { W.__log = []; W.__pl = 1; W.__fin = false; play(name + '-p1'); autoAcc(300); (async () => { for (let n = 2; n <= N; n++) { while (!W.__rdone) await slp(1000); await slp(1500); W.__log.push('--- play ' + n); play(name + '-p' + n); W.__pl = n; autoAcc(300); await slp(3000); } while (!W.__rdone) await slp(1000); W.__fin = true; })(); return 'started' };
})();
